{"command":"cat <<'EOF' > main.go
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

type RequestItemType int

const (
	ItemQuery RequestItemType = iota
	ItemData
	ItemDataJSON
	ItemHeader
	ItemHeaderUnset
	ItemHeaderEmpty
	ItemFile
	ItemRawBody
)

type RequestItem struct {
	Type  RequestItemType
	Key   string
	Value string
}

type Config struct {
	Method       string
	URL          string
	RequestItems []RequestItem
	JSON         bool
	Form         bool
	Multipart    bool
	Offline      bool
	IgnoreStdin  bool
	Verbose      int
	Print        string
	Headers      bool
	Body         bool
	Meta         bool
	Curl         bool
	Scheme       string
}

func main() {
	binaryName := filepath.Base(os.Args[0])
	scheme := "http://"
	if binaryName == "xhs" {
		scheme = "https://"
	}

	config := Config{
		JSON:   true,
		Scheme: scheme,
		Print:  "hb", // Default if not specified? Let's check.
	}

	var posArgs []string
	args := os.Args[1:]

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if strings.HasPrefix(arg, "-") {
			if arg == "--" {
				posArgs = append(posArgs, args[i+1:]...)
				break
			}
			// Handle flags
			if arg == "--offline" {
				config.Offline = true
			} else if arg == "-I" || arg == "--ignore-stdin" {
				config.IgnoreStdin = true
			} else if arg == "-j" || arg == "--json" {
				config.JSON = true
				config.Form = false
				config.Multipart = false
			} else if arg == "-f" || arg == "--form" {
				config.Form = true
				config.JSON = false
				config.Multipart = false
			} else if arg == "--multipart" {
				config.Multipart = true
				config.JSON = false
				config.Form = false
			} else if arg == "--curl" {
				config.Curl = true
			} else if arg == "-v" || arg == "--verbose" {
				config.Verbose++
			} else if arg == "-h" || arg == "--headers" {
				config.Headers = true
			} else if arg == "-b" || arg == "--body" {
				config.Body = true
			} else if arg == "-m" || arg == "--meta" {
				config.Meta = true
			} else if arg == "-p" || arg == "--print" {
				if i+1 < len(args) {
					config.Print = args[i+1]
					i++
				}
			} else if strings.HasPrefix(arg, "--print=") {
				config.Print = arg[len("--print="):]
			}
			// Add more flags here
		} else {
			posArgs = append(posArgs, arg)
		}
	}

	if len(posArgs) == 0 {
		fmt.Fprintf(os.Stderr, "error: Missing <URL>\n")
		os.Exit(2)
	}

	// Determine Method and URL
	if len(posArgs) >= 2 && !isRequestItem(posArgs[0]) && !isRequestItem(posArgs[1]) {
		config.Method = strings.ToUpper(posArgs[0])
		config.URL = posArgs[1]
		for _, item := range posArgs[2:] {
			config.RequestItems = append(config.RequestItems, parseRequestItem(item))
		}
	} else {
		config.URL = posArgs[0]
		for _, item := range posArgs[1:] {
			config.RequestItems = append(config.RequestItems, parseRequestItem(item))
		}
	}

	// Default method
	if config.Method == "" {
		hasBody := false
		for _, item := range config.RequestItems {
			if item.Type == ItemData || item.Type == ItemDataJSON || item.Type == ItemFile || item.Type == ItemRawBody {
				hasBody = true
				break
			}
		}
		if hasBody {
			config.Method = "POST"
		} else {
			config.Method = "GET"
		}
	}

	// Final URL handling
	if !strings.Contains(config.URL, "://") {
		if strings.HasPrefix(config.URL, ":") {
			config.URL = "localhost" + config.URL
		}
		config.URL = config.Scheme + config.URL
	}

	if config.Offline {
		printOfflineRequest(config)
	}
}

func isRequestItem(arg string) bool {
	return strings.ContainsAny(arg, "=:@;") || strings.HasPrefix(arg, "@")
}

func parseRequestItem(arg string) RequestItem {
	if strings.HasPrefix(arg, "@") {
		return RequestItem{Type: ItemRawBody, Value: arg[1:]}
	}
	if idx := strings.Index(arg, "=="); idx != -1 {
		return RequestItem{Type: ItemQuery, Key: arg[:idx], Value: arg[idx+2:]}
	}
	if idx := strings.Index(arg, ":="); idx != -1 {
		return RequestItem{Type: ItemDataJSON, Key: arg[:idx], Value: arg[idx+2:]}
	}
	if idx := strings.Index(arg, "="); idx != -1 {
		return RequestItem{Type: ItemData, Key: arg[:idx], Value: arg[idx+1:]}
	}
	if idx := strings.Index(arg, "@"); idx != -1 {
		return RequestItem{Type: ItemFile, Key: arg[:idx], Value: arg[idx+1:]}
	}
	if idx := strings.Index(arg, ":"); idx != -1 {
		if idx == len(arg)-1 {
			return RequestItem{Type: ItemHeaderUnset, Key: arg[:idx]}
		}
		return RequestItem{Type: ItemHeader, Key: arg[:idx], Value: arg[idx+1:]}
	}
	if strings.HasSuffix(arg, ";") {
		return RequestItem{Type: ItemHeaderEmpty, Key: arg[:len(arg)-1]}
	}
	return RequestItem{Type: ItemData, Key: arg, Value: ""} // Should not happen if isRequestItem is correct
}

func printOfflineRequest(config Config) {
	fmt.Printf("%s %s HTTP/1.1\n", config.Method, config.URL)
	for _, item := range config.RequestItems {
		if item.Type == ItemHeader {
			fmt.Printf("%s: %s\n", item.Key, item.Value)
		}
	}
	fmt.Println()
}
