func isRequestItem(arg string) bool {
	return strings.ContainsAny(arg, "=:@;") || strings.HasPrefix(arg, "@")
}

func isBodyItem(t RequestItemType) bool {
	return t == ItemData || t == ItemDataJSON || t == ItemFile || t == ItemRawBody
}

func parseRequestItem(arg string) RequestItem {
	if strings.HasPrefix(arg, "@") {
		return RequestItem{Type: ItemRawBody, Value: arg[1:]}
	}
	if idx := strings.Index(arg, "=="); idx != -1 {
		return RequestItem{Type: ItemQuery, Key: arg[:idx], Value: arg[idx+2:]}
	}
	if idx := strings.Index(arg, ":="); idx != -1 {
		return RequestItem{Type: ItemDataJSON, Key: arg[:idx], Value: arg[idx+2:]}
	}
	if idx := strings.Index(arg, "="); idx != -1 {
		return RequestItem{Type: ItemData, Key: arg[:idx], Value: arg[idx+1:]}
	}
	if idx := strings.Index(arg, "@"); idx != -1 {
		return RequestItem{Type: ItemFile, Key: arg[:idx], Value: arg[idx+1:]}
	}
	if idx := strings.Index(arg, ":"); idx != -1 {
		if idx == len(arg)-1 {
			return RequestItem{Type: ItemHeaderUnset, Key: arg[:idx]}
		}
		return RequestItem{Type: ItemHeader, Key: arg[:idx], Value: arg[idx+1:]}
	}
	if strings.HasSuffix(arg, ";") {
		return RequestItem{Type: ItemHeaderEmpty, Key: arg[:len(arg)-1]}
	}
	return RequestItem{Type: ItemData, Key: arg, Value: ""}
}

func isTTY(f *os.File) bool {
	fi, _ := f.Stat()
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func setNested(m map[string]interface{}, path string, value interface{}) {
	parts := strings.FieldsFunc(path, func(r rune) bool {
		return r == '[' || r == ']'
	})
	if len(parts) == 0 {
		return
	}
	curr := m
	for i := 0; i < len(parts)-1; i++ {
		key := parts[i]
		if _, ok := curr[key]; !ok {
			curr[key] = make(map[string]interface{})
		}
		if next, ok := curr[key].(map[string]interface{}); ok {
			curr = next
		} else {
			newMap := make(map[string]interface{})
			curr[key] = newMap
			curr = newMap
		}
	}
	curr[parts[len(parts)-1]] = value
}

func printRequest(req *http.Request, body []byte, color bool) {
	u := req.URL
	path := u.Path
	if u.RawQuery != "" {
		path += "?" + u.RawQuery
	}

	if color {
		fmt.Printf("%s%s %s%s %s%s%s\n", ColorBold, req.Method, ColorCyan, path, ColorGray, req.Proto, ColorOff)
	} else {
		fmt.Printf("%s %s %s\n", req.Method, path, req.Proto)
	}

	headers := req.Header
	keys := make([]string, 0, len(headers)+1)
	for k := range headers {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	printHeader := func(k, v string) {
		if color {
			fmt.Printf("%s%s%s: %s%s%s\n", ColorCyan, k, ColorOff, ColorCyan, v, ColorOff)
		} else {
			fmt.Printf("%s: %s\n", k, v)
		}
	}

	printHeader("Host", u.Host)
	for _, k := range keys {
		printHeader(k, headers.Get(k))
	}
	if len(body) > 0 {
		printHeader("Content-Length", fmt.Sprintf("%d", len(body)))
	}
	fmt.Println()
