	"time"
)

type RequestItemType int

const (
	ItemQuery RequestItemType = iota
	ItemData
	ItemDataJSON
	ItemHeader
	ItemHeaderUnset
	ItemHeaderEmpty
	ItemFile
	ItemRawBody
)

type RequestItem struct {
	Type  RequestItemType
	Key   string
	Value string
}

type Config struct {
	Method       string
	URL          string
	RequestItems []RequestItem
	JSON         bool
	Form         bool
	Multipart    bool
	Offline      bool
	IgnoreStdin  bool
	Verbose      int
	Print        string
	HeadersOnly  bool
	BodyOnly     bool
	MetaOnly     bool
	Curl         bool
	Scheme       string
	Follow       bool
	Timeout      time.Duration
	CheckStatus  bool
	Auth         string
	AuthType     string
	Https        bool
}

const (
	ColorOff    = "\033[0m"
	ColorBlue   = "\033[34m"
	ColorCyan   = "\033[36m"
	ColorGreen  = "\033[32m"
	ColorYellow = "\033[33m"
	ColorBold   = "\033[1m"
	ColorRed    = "\033[31m"
	ColorGray   = "\033[90m"
)

func main() {
	binaryName := filepath.Base(os.Args[0])
	scheme := "http://"
	if binaryName == "xhs" {
		scheme = "https://"
	}

	config := Config{
		JSON:        true,
		Scheme:      scheme,
		CheckStatus: true,
		AuthType:    "basic",
	}

	var posArgs []string
	args := os.Args[1:]

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if strings.HasPrefix(arg, "-") && arg != "-" {
			if arg == "--" {
				posArgs = append(posArgs, args[i+1:]...)
				break
			}
			if arg == "--offline" {
				config.Offline = true
			} else if arg == "-I" || arg == "--ignore-stdin" {
				config.IgnoreStdin = true
			} else if arg == "-j" || arg == "--json" {
				config.JSON = true
				config.Form = false
				config.Multipart = false
			} else if arg == "-f" || arg == "--form" {
				config.Form = true
				config.JSON = false
				config.Multipart = false
			} else if arg == "--multipart" {
				config.Multipart = true
				config.JSON = false
				config.Form = false
			} else if arg == "--curl" {
				config.Curl = true
			} else if arg == "-v" || arg == "--verbose" {
				config.Verbose++
			} else if arg == "-h" || arg == "--headers" {
				config.HeadersOnly = true
			} else if arg == "-b" || arg == "--body" {
				config.BodyOnly = true
			} else if arg == "-m" || arg == "--meta" {
				config.MetaOnly = true
			} else if arg == "-F" || arg == "--follow" {
				config.Follow = true
			} else if arg == "--no-check-status" {
				config.CheckStatus = false
			} else if arg == "--https" {
				config.Https = true
				config.Scheme = "https://"
			} else if arg == "-a" || arg == "--auth" {
				if i+1 < len(args) {
					config.Auth = args[i+1]
					i++
				}
			} else if arg == "-A" || arg == "--auth-type" {
				if i+1 < len(args) {
					config.AuthType = args[i+1]
					i++
				}
			} else if arg == "-p" || arg == "--print" {
				if i+1 < len(args) {
					config.Print = args[i+1]
					i++
				}
			} else if strings.HasPrefix(arg, "--print=") {
				config.Print = arg[len("--print="):]
			} else if arg == "--timeout" {
				if i+1 < len(args) {
					t, _ := time.ParseDuration(args[i+1] + "s")
					config.Timeout = t
					i++
				}
			}
		} else {
			posArgs = append(posArgs, arg)
		}
	}

