	for _, item := range config.RequestItems {
		if item.Type == ItemQuery {
			q.Add(item.Key, item.Value)
		}
	}
	u.RawQuery = q.Encode()

	var body []byte
	var bodyReader io.Reader
	contentType := ""

	if config.JSON {
		bodyMap := make(map[string]interface{})
		for _, item := range config.RequestItems {
			if item.Type == ItemData {
				setNested(bodyMap, item.Key, item.Value)
			} else if item.Type == ItemDataJSON {
				var val interface{}
				if err := json.Unmarshal([]byte(item.Value), &val); err == nil {
					setNested(bodyMap, item.Key, val)
				} else {
					setNested(bodyMap, item.Key, item.Value)
				}
			}
		}
		if len(bodyMap) > 0 {
			body, _ = json.Marshal(bodyMap)
			contentType = "application/json"
		} else if !config.IgnoreStdin && !isTTY(os.Stdin) {
			body, _ = io.ReadAll(os.Stdin)
			contentType = "application/json"
		}
	} else if config.Form {
		form := url.Values{}
		for _, item := range config.RequestItems {
			if item.Type == ItemData {
				form.Add(item.Key, item.Value)
			}
		}
		body = []byte(form.Encode())
		contentType = "application/x-www-form-urlencoded"
	}

	if len(body) > 0 {
		bodyReader = bytes.NewReader(body)
	}

	req, _ := http.NewRequest(config.Method, u.String(), bodyReader)

	req.Header.Set("User-Agent", "xh/0.25.3")
	req.Header.Set("Accept-Encoding", "gzip, deflate, br, zstd")
	req.Header.Set("Connection", "keep-alive")

	if config.JSON {
		req.Header.Set("Accept", "application/json, */*;q=0.5")
		if contentType != "" {
			req.Header.Set("Content-Type", contentType)
		} else if config.Method != "GET" && config.Method != "HEAD" {
			req.Header.Set("Content-Type", "application/json")
		}
	} else {
		req.Header.Set("Accept", "*/*")
		if contentType != "" {
			req.Header.Set("Content-Type", contentType)
		}
	}

	if config.Auth != "" {
		if config.AuthType == "basic" {
			parts := strings.SplitN(config.Auth, ":", 2)
			user := parts[0]
			pass := ""
			if len(parts) > 1 {
				pass = parts[1]
			}
			auth := base64.StdEncoding.EncodeToString([]byte(user + ":" + pass))
			req.Header.Set("Authorization", "Basic "+auth)
		} else if config.AuthType == "bearer" {
			req.Header.Set("Authorization", "Bearer "+config.Auth)
		}
	}

	for _, item := range config.RequestItems {
		if item.Type == ItemHeader {
			req.Header.Set(item.Key, item.Value)
		} else if item.Type == ItemHeaderEmpty {
			req.Header.Set(item.Key, "")
		} else if item.Type == ItemHeaderUnset {
			req.Header.Del(item.Key)
		}
	}

	if config.Curl {
		printCurl(req, body)
		return
	}

	if config.Offline {
		printRequest(req, body, isTTY(os.Stdout))
		return
	}

	client := &http.Client{
		Timeout: config.Timeout,
	}
	if !config.Follow {
		client.CheckRedirect = func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		}
	}

	if config.Verbose > 0 {
		printRequest(req, body, isTTY(os.Stdout))
		fmt.Println()
	}

	resp, err := client.Do(req)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	defer resp.Body.Close()

	printResponse(resp, config)

	if config.CheckStatus {
		if resp.StatusCode >= 500 {
			os.Exit(5)
		} else if resp.StatusCode >= 400 {
			os.Exit(4)
		} else if resp.StatusCode >= 300 && !config.Follow {
			os.Exit(3)
		}
	}
}

