	Method       string
	URL          string
	RequestItems []RequestItem
	JSON         bool
	Form         bool
	Multipart    bool
	Offline      bool
	IgnoreStdin  bool
	Verbose      int
	Print        string
	HeadersOnly  bool
	BodyOnly     bool
	MetaOnly     bool
	Curl         bool
	Scheme       string
	Follow       bool
	Timeout      time.Duration
	CheckStatus  bool
	Auth         string
	AuthType     string
	Https        bool
}

const (
	ColorOff    = "\033[0m"
	ColorBlue   = "\033[34m"
	ColorCyan   = "\033[36m"
	ColorGreen  = "\033[32m"
	ColorYellow = "\033[33m"
	ColorBold   = "\033[1m"
	ColorRed    = "\033[31m"
	ColorGray   = "\033[90m"
)

func main() {
	binaryName := filepath.Base(os.Args[0])
	scheme := "http://"
	if binaryName == "xhs" {
		scheme = "https://"
	}

	config := Config{
		JSON:        true,
		Scheme:      scheme,
		CheckStatus: true,
		AuthType:    "basic",
	}

	var posArgs []string
	args := os.Args[1:]

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if strings.HasPrefix(arg, "-") && arg != "-" {
			if arg == "--" {
				posArgs = append(posArgs, args[i+1:]...)
				break
			}
			if arg == "--offline" {
				config.Offline = true
			} else if arg == "-I" || arg == "--ignore-stdin" {
				config.IgnoreStdin = true
			} else if arg == "-j" || arg == "--json" {
				config.JSON = true
				config.Form = false
				config.Multipart = false
			} else if arg == "-f" || arg == "--form" {
				config.Form = true
				config.JSON = false
				config.Multipart = false
			} else if arg == "--multipart" {
				config.Multipart = true
				config.JSON = false
				config.Form = false
			} else if arg == "--curl" {
				config.Curl = true
			} else if arg == "-v" || arg == "--verbose" {
				config.Verbose++
			} else if arg == "-h" || arg == "--headers" {
				config.HeadersOnly = true
			} else if arg == "-b" || arg == "--body" {
				config.BodyOnly = true
			} else if arg == "-m" || arg == "--meta" {
				config.MetaOnly = true
			} else if arg == "-F" || arg == "--follow" {
				config.Follow = true
			} else if arg == "--no-check-status" {
				config.CheckStatus = false
			} else if arg == "--https" {
				config.Https = true
				config.Scheme = "https://"
			} else if arg == "-a" || arg == "--auth" {
				if i+1 < len(args) {
					config.Auth = args[i+1]
					i++
				}
			} else if arg == "-A" || arg == "--auth-type" {
				if i+1 < len(args) {
					config.AuthType = args[i+1]
					i++
				}
			} else if arg == "-p" || arg == "--print" {
				if i+1 < len(args) {
					config.Print = args[i+1]
					i++
				}
			} else if strings.HasPrefix(arg, "--print=") {
				config.Print = arg[len("--print="):]
			} else if arg == "--timeout" {
				if i+1 < len(args) {
					t, _ := time.ParseDuration(args[i+1] + "s")
					config.Timeout = t
					i++
				}
			}
		} else {
			posArgs = append(posArgs, arg)
		}
	}

	if len(posArgs) == 0 {
		fmt.Fprintf(os.Stderr, "error: Missing <URL>\n")
		os.Exit(2)
	}

	if len(posArgs) >= 2 && !isRequestItem(posArgs[0]) && !isRequestItem(posArgs[1]) {
		config.Method = strings.ToUpper(posArgs[0])
		config.URL = posArgs[1]
		for _, item := range posArgs[2:] {
			config.RequestItems = append(config.RequestItems, parseRequestItem(item))
		}
	} else {
		config.URL = posArgs[0]
		for _, item := range posArgs[1:] {
			config.RequestItems = append(config.RequestItems, parseRequestItem(item))
		}
	}

	if config.Method == "" {
		hasBody := false
		for _, item := range config.RequestItems {
			if isBodyItem(item.Type) {
				hasBody = true
				break
			}
		}
		if !config.IgnoreStdin && !isTTY(os.Stdin) {
			hasBody = true
		}
		if hasBody {
			config.Method = "POST"
		} else {
			config.Method = "GET"
		}
	}

	if !strings.Contains(config.URL, "://") {
		if strings.HasPrefix(config.URL, ":") {
			config.URL = "localhost" + config.URL
		}
		config.URL = config.Scheme + config.URL
	}

	u, err := url.Parse(config.URL)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: Invalid URL: %v\n", err)
		os.Exit(1)
	}
	if u.Path == "" {
		u.Path = "/"
	}

	q := u.Query()
	for _, item := range config.RequestItems {
		if item.Type == ItemQuery {
			q.Add(item.Key, item.Value)
		}
	}
	u.RawQuery = q.Encode()

	var body []byte
	var bodyReader io.Reader
	contentType := ""

	if config.JSON {
		bodyMap := make(map[string]interface{})
		for _, item := range config.RequestItems {
			if item.Type == ItemData {
				setNested(bodyMap, item.Key, item.Value)
			} else if item.Type == ItemDataJSON {
				var val interface{}
				if err := json.Unmarshal([]byte(item.Value), &val); err == nil {
					setNested(bodyMap, item.Key, val)
				} else {
					setNested(bodyMap, item.Key, item.Value)
				}
			}
		}
		if len(bodyMap) > 0 {
			body, _ = json.Marshal(bodyMap)
			contentType = "application/json"
		} else if !config.IgnoreStdin && !isTTY(os.Stdin) {
			body, _ = io.ReadAll(os.Stdin)
			contentType = "application/json"
		}
	} else if config.Form {
		form := url.Values{}
		for _, item := range config.RequestItems {
			if item.Type == ItemData {
				form.Add(item.Key, item.Value)
			}
		}
		body = []byte(form.Encode())
		contentType = "application/x-www-form-urlencoded"
	}

	if len(body) > 0 {
		bodyReader = bytes.NewReader(body)
	}

	req, _ := http.NewRequest(config.Method, u.String(), bodyReader)

	req.Header.Set("User-Agent", "xh/0.25.3")
	req.Header.Set("Accept-Encoding", "gzip, deflate, br, zstd")
	req.Header.Set("Connection", "keep-alive")

	if config.JSON {
		req.Header.Set("Accept", "application/json, */*;q=0.5")
		if contentType != "" {
			req.Header.Set("Content-Type", contentType)
		} else if config.Method != "GET" && config.Method != "HEAD" {
			req.Header.Set("Content-Type", "application/json")
		}
	} else {
		req.Header.Set("Accept", "*/*")
		if contentType != "" {
			req.Header.Set("Content-Type", contentType)
		}
	}

	if config.Auth != "" {
		if config.AuthType == "basic" {
			parts := strings.SplitN(config.Auth, ":", 2)
			user := parts[0]
			pass := ""
			if len(parts) > 1 {
				pass = parts[1]
			}
			auth := base64.StdEncoding.EncodeToString([]byte(user + ":" + pass))
			req.Header.Set("Authorization", "Basic "+auth)
		} else if config.AuthType == "bearer" {
			req.Header.Set("Authorization", "Bearer "+config.Auth)
		}
	}

	for _, item := range config.RequestItems {
		if item.Type == ItemHeader {
			req.Header.Set(item.Key, item.Value)
		} else if item.Type == ItemHeaderEmpty {
			req.Header.Set(item.Key, "")
		} else if item.Type == ItemHeaderUnset {
			req.Header.Del(item.Key)
		}
	}

	if config.Curl {
		printCurl(req, body)
		return
	}

	if config.Offline {
		printRequest(req, body, isTTY(os.Stdout))
		return
	}

	client := &http.Client{
		Timeout: config.Timeout,
	}
	if !config.Follow {
		client.CheckRedirect = func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		}
	}

	if config.Verbose > 0 {
		printRequest(req, body, isTTY(os.Stdout))
		fmt.Println()
	}

	resp, err := client.Do(req)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	defer resp.Body.Close()

	printResponse(resp, config)

	if config.CheckStatus {
		if resp.StatusCode >= 500 {
			os.Exit(5)
		} else if resp.StatusCode >= 400 {
			os.Exit(4)
		} else if resp.StatusCode >= 300 && !config.Follow {
			os.Exit(3)
		}
	}
}

func isRequestItem(arg string) bool {
	return strings.ContainsAny(arg, "=:@;") || strings.HasPrefix(arg, "@")
}

func isBodyItem(t RequestItemType) bool {
	return t == ItemData || t == ItemDataJSON || t == ItemFile || t == ItemRawBody
}

func parseRequestItem(arg string) RequestItem {
	if strings.HasPrefix(arg, "@") {
		return RequestItem{Type: ItemRawBody, Value: arg[1:]}
	}
	if idx := strings.Index(arg, "=="); idx != -1 {
		return RequestItem{Type: ItemQuery, Key: arg[:idx], Value: arg[idx+2:]}
	}
	if idx := strings.Index(arg, ":="); idx != -1 {
		return RequestItem{Type: ItemDataJSON, Key: arg[:idx], Value: arg[idx+2:]}
	}
	if idx := strings.Index(arg, "="); idx != -1 {
		return RequestItem{Type: ItemData, Key: arg[:idx], Value: arg[idx+1:]}
	}
	if idx := strings.Index(arg, "@"); idx != -1 {
		return RequestItem{Type: ItemFile, Key: arg[:idx], Value: arg[idx+1:]}
	}
	if idx := strings.Index(arg, ":"); idx != -1 {
		if idx == len(arg)-1 {
			return RequestItem{Type: ItemHeaderUnset, Key: arg[:idx]}
		}
		return RequestItem{Type: ItemHeader, Key: arg[:idx], Value: arg[idx+1:]}
	}
	if strings.HasSuffix(arg, ";") {
		return RequestItem{Type: ItemHeaderEmpty, Key: arg[:len(arg)-1]}
	}
	return RequestItem{Type: ItemData, Key: arg, Value: ""}
}

func isTTY(f *os.File) bool {
	fi, _ := f.Stat()
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func setNested(m map[string]interface{}, path string, value interface{}) {
	parts := strings.FieldsFunc(path, func(r rune) bool {
		return r == '[' || r == ']'
	})
	if len(parts) == 0 {
		return
	}
	curr := m
	for i := 0; i < len(parts)-1; i++ {
		key := parts[i]
		if _, ok := curr[key]; !ok {
			curr[key] = make(map[string]interface{})
		}
		if next, ok := curr[key].(map[string]interface{}); ok {
			curr = next
		} else {
			newMap := make(map[string]interface{})
			curr[key] = newMap
			curr = newMap
		}
	}
	curr[parts[len(parts)-1]] = value
}

func printRequest(req *http.Request, body []byte, color bool) {
	u := req.URL
	path := u.Path
	if u.RawQuery != "" {
		path += "?" + u.RawQuery
	}

	if color {
		fmt.Printf("%s%s %s%s %s%s%s\n", ColorBold, req.Method, ColorCyan, path, ColorGray, req.Proto, ColorOff)
	} else {
		fmt.Printf("%s %s %s\n", req.Method, path, req.Proto)
	}

	headers := req.Header
	keys := make([]string, 0, len(headers)+1)
	for k := range headers {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	printHeader := func(k, v string) {
		if color {
			fmt.Printf("%s%s%s: %s%s%s\n", ColorCyan, k, ColorOff, ColorCyan, v, ColorOff)
		} else {
			fmt.Printf("%s: %s\n", k, v)
		}
	}

	printHeader("Host", u.Host)
	for _, k := range keys {
		printHeader(k, headers.Get(k))
	}
	if len(body) > 0 {
		printHeader("Content-Length", fmt.Sprintf("%d", len(body)))
	}
	fmt.Println()
	if len(body) > 0 {
		if color && isJSON(headers.Get("Content-Type")) {
			fmt.Println(colorJSON(body))
		} else {
			fmt.Println(string(body))
		}
	}
}

func printResponse(resp *http.Response, config Config) {
	color := isTTY(os.Stdout)
	printHeaders := !config.BodyOnly && !config.MetaOnly
	printBody := !config.HeadersOnly && !config.MetaOnly

	if config.Print != "" {
		printHeaders = strings.Contains(config.Print, "h")
		printBody = strings.Contains(config.Print, "b")
	}

	if printHeaders {
		if color {
			fmt.Printf("%s%s %s%s\n", ColorGray, resp.Proto, ColorBold, resp.Status)
		} else {
			fmt.Printf("%s %s\n", resp.Proto, resp.Status)
		}
		var keys []string
		for k := range resp.Header {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			if color {
				fmt.Printf("%s%s%s: %s%s%s\n", ColorCyan, k, ColorOff, ColorCyan, resp.Header.Get(k), ColorOff)
			} else {
				fmt.Printf("%s: %s\n", k, resp.Header.Get(k))
			}
		}
		fmt.Println()
	}

	if printBody {
		body, _ := io.ReadAll(resp.Body)
		if isJSON(resp.Header.Get("Content-Type")) && color {
			fmt.Println(colorJSON(body))
		} else {
			fmt.Print(string(body))
			if len(body) > 0 && !strings.HasSuffix(string(body), "\n") && isTTY(os.Stdout) {
				fmt.Println()
			}
		}
	}
}

func isJSON(ct string) bool {
	return strings.Contains(ct, "application/json")
}

func colorJSON(body []byte) string {
	var prettyJSON bytes.Buffer
	if err := json.Indent(&prettyJSON, body, "", "    "); err != nil {
		return string(body)
	}
	return prettyJSON.String()
}

func printCurl(req *http.Request, body []byte) {
	var args []string
	args = append(args, "curl")
	if req.Method != "GET" && req.Method != "POST" {
		args = append(args, "-X", req.Method)
	}
	args = append(args, fmt.Sprintf("'%s'", req.URL.String()))

	var keys []string
	for k := range req.Header {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		args = append(args, "-H", fmt.Sprintf("'%s: %s'", strings.ToLower(k), req.Header.Get(k)))
	}
	if len(body) > 0 {
		args = append(args, "-d", fmt.Sprintf("'%s'", string(body)))
	}
	fmt.Println(strings.Join(args, " "))
}
